import type { Readable } from "stream";

export interface DownloaderMetadata {
  Author: string;
  message: string;
  Facebook: string;
}

export interface PickedAudio {
  format: string | null;
  bitrate: number | null;
  savedAs: string;
  requestedFormat: string | null;
  requestedBitrate: number | null;
  formatFallback: boolean;
}

export interface NormalizedData {
  title: string;
  videoUrl: string;
  source: string;
  download?: unknown;

  subtitles?: SubtitleTrack[];

  note?: string;

  images?: Array<{ url: string }>;

  pickedQuality?: string;

  pickedVideoOnly?: boolean;

  pickedAudio?: PickedAudio;

  uploader?: string | null;
}

export type QualityOption =
  | "best"
  | "high"
  | "medium"
  | "low"
  | "worst"
  | "audio"
  | "4k"
  | `${number}p`
  | `${number}`;

export interface NormalizedResult {
  metadata: DownloaderMetadata;
  data: NormalizedData;
}

export interface PlatformData {
  title?: string;
  author?: string;
  thumbnail?: string | null;
  download?: unknown;
  stats?: unknown;
  [key: string]: unknown;
}

export interface PlatformResult {
  metadata: DownloaderMetadata;
  success: boolean;
  source: string;
  data: PlatformData;
}

export type AudioFormat = "mp3" | "m4a" | "wav" | "opus";

export interface AllDLOptions {

  retries?: number;

  quality?: QualityOption;

  maxHeight?: number;

  audioOnly?: boolean;

  audioBitrate?: 128 | 192 | 320 | number;

  audioFormat?: AudioFormat;

  thumbnail?: boolean;

  proxy?: string | string[] | null;

  proxies?: string | string[] | null;

  subtitles?: boolean | string;
}

export interface DownloadProgress {
  done: number;
  total: number | null;
  percent: number | null;
}

export interface StreamOptions extends AllDLOptions {

  onProgress?: (p: DownloadProgress) => void;
}

export interface MediaStream extends Readable {

  title?: string | null;

  source?: string | null;

  videoUrl?: string;

  pickedQuality?: string;

  pickedVideoOnly?: boolean;

  pickedAudio?: PickedAudio;
}

export interface DownloadOptions extends AllDLOptions {

  onProgress?: (p: DownloadProgress) => void;

  audioOnly?: boolean;

  resume?: boolean;

  connections?: number;

  chunkRetries?: number;

  tag?: boolean;
}

export interface PlaylistVideo {
  videoId: string;
  title: string;
  url: string;

  mediaUrl?: string;
}

export interface PlaylistResult {
  title: string;
  count: number;
  videos: PlaylistVideo[];
}

export interface SubtitleResult {
  lang: string;
  srt: string;
  path?: string;
}

export interface SubtitleTrack {

  lang: string;

  name: string;

  url: string;
}

export interface SourceHealthEntry {

  fails: number;

  inCooldown: boolean;

  cooldownEndsIn: number;
}

export interface SourceHealthMap {
  [sourceId: string]: SourceHealthEntry;
}

export interface SourceStatusMap {
  [platform: string]: { [sourceId: string]: "up" | "down" };
}

export interface DownloadResult {
  path: string;
  bytes: number;
  title: string;
  source: string;
  videoUrl: string;

  note?: string;

  subtitlePath?: string;

  pickedQuality?: string;

  pickedVideoOnly?: boolean;

  pickedAudio?: PickedAudio;

  thumbnailPath?: string | null;

  thumbnailNote?: string;
}

export interface RecordLiveProgress {
  segments: number;
  bytes: number;
  elapsed: number;
  percent: number;
}

export interface RecordLiveOptions {
  duration?: number;
  dest?: string;
  quality?: QualityOption;
  proxy?: string | string[] | null;
  proxies?: string | string[] | null;
  onProgress?: (p: RecordLiveProgress) => void;
}

export interface RecordLiveResult {
  path: string;
  bytes: number;
  segments: number;
  secondsRecorded: number;
  duration: number;
  title: string;
  source: string;
  endedEarly: boolean;
  live: boolean;
  note?: string;
}

export interface PlaylistOptions {

  limit?: number;

  proxy?: string | string[] | null;

  proxies?: string | string[] | null;
}

export interface PlaylistDownloadOptions extends DownloadOptions {

  limit?: number;

  concurrency?: number;

  dest?: string;

  dir?: string;

  onItem?: (item: PlaylistDownloadItem, index: number) => void;
}

export type PlaylistDownloadItem =
  | { url: string; ok: true; title: string; path: string; bytes: number; videoUrl: string; note?: string; subtitlePath?: string }
  | { url: string; ok: false; title: string; error: string };

export interface PlaylistDownloadResult {
  title: string;
  count: number;
  results: PlaylistDownloadItem[];
}

export interface ProxyHealthEntry {

  fails: number;

  inCooldown: boolean;

  cooldownEndsIn: number;
}

export interface ProxyStats {

  mode: string;

  list: string[] | null;

  current: unknown;

  proxies: { [url: string]: ProxyHealthEntry };
}

export interface SearchOptions extends AllDLOptions {

  platform?: "youtube" | "tiktok" | "yt";

  limit?: number;

  minDuration?: number;

  maxDuration?: number;

  minViews?: number;

  maxViews?: number;

  itemOpts?: AllDLOptions;
}

export interface SearchResultItem {
  id: string;
  title: string | null;
  url: string;
  author: string | null;
  duration: string | null;
  thumbnail: string | null;
  views?: string | null;
}

export interface SearchDownloadResult {
  query: string;
  picked: SearchResultItem;
  result: NormalizedResult;
}

export interface CacheStats {
  size: number;
  ttlMs: number;
  maxEntries: number;
}

export interface BatchOptions extends AllDLOptions {

  concurrency?: number;

  onProgress?: (done: number, total: number, item: BatchItem) => void;
}

export type BatchItem =
  | { ok: true; url: string; result: NormalizedResult }
  | { ok: false; url: string; error: string };

export interface XOptions {

  quality?: string;
}

export interface InfoAuthor {
  name: string | null;
  url: string | null;
}

export interface InfoResult {

  site: string;

  platform: string;
  url: string;
  title: string | null;
  author: InfoAuthor;

  uploader: string | null;

  thumbnail: string | null;
  duration: number | null;
  description: string | null;
}

export interface InfoOptions {

  appToken?: string;
}

export interface AllDL {

  (url: string, opts?: AllDLOptions): Promise<NormalizedResult>;

  download(url: string, dest: string, opts?: DownloadOptions): Promise<DownloadResult>;

  stream(url: string, opts?: StreamOptions): Promise<MediaStream>;

  buffer(url: string, opts?: StreamOptions): Promise<Buffer>;

  isSupported(url: string): boolean;

  detectPlatform(url: string): string | null;

  recordLive(url: string, opts?: RecordLiveOptions): Promise<RecordLiveResult>;

  batch(urls: string[], opts?: BatchOptions): Promise<BatchItem[]>;

  search(query: string, opts?: SearchOptions): Promise<SearchResultItem[]>;

  searchDownload(query: string, opts?: SearchOptions): Promise<SearchDownloadResult>;

  setCookie(platform: string, cookie: string): boolean;

  clearCookies(platform?: string): void;

  clearCache(): void;

  cacheStats(): CacheStats;

  tiktok(url: string): Promise<PlatformResult>;

  fb(url: string): Promise<PlatformResult>;

  insta(url: string): Promise<PlatformResult>;

  likee(url: string): Promise<PlatformResult>;

  threads(url: string): Promise<PlatformResult>;

  pinterest(url: string): Promise<PlatformResult>;

  youtube(url: string): Promise<PlatformResult>;

  capcut(url: string): Promise<PlatformResult>;

  kwai(url: string): Promise<PlatformResult>;

  dailymotion(url: string): Promise<PlatformResult>;

  vimeo(url: string): Promise<PlatformResult>;

  niconico(url: string): Promise<PlatformResult>;

  naver(url: string): Promise<PlatformResult>;

  x(url: string, opts?: XOptions): Promise<PlatformResult>;

  twitter(url: string, opts?: XOptions): Promise<PlatformResult>;

  snapchat(url: string): Promise<PlatformResult>;

  reddit(url: string): Promise<PlatformResult>;

  moj(url: string): Promise<PlatformResult>;

  josh(url: string): Promise<PlatformResult>;

  rumble(url: string): Promise<PlatformResult>;

  twitch(url: string): Promise<PlatformResult>;

  terabox(url: string): Promise<PlatformResult>;

  gdrive(url: string): Promise<PlatformResult>;

  mega(url: string): Promise<PlatformResult>;

  mediafire(url: string): Promise<PlatformResult>;

  bilibili(url: string): Promise<PlatformResult>;

  soundcloud(url: string): Promise<PlatformResult>;

  spotify(url: string): Promise<PlatformResult>;

  douyin(url: string): Promise<PlatformResult>;

  xiaohongshu(url: string): Promise<PlatformResult>;

  deezer(url: string): Promise<PlatformResult>;

  applemusic(url: string): Promise<PlatformResult>;

  bandcamp(url: string): Promise<PlatformResult>;

  pixeldrain(url: string): Promise<PlatformResult>;

  gofile(url: string): Promise<PlatformResult>;

  odysee(url: string): Promise<PlatformResult>;

  peertube(url: string): Promise<PlatformResult>;

  kick(url: string): Promise<PlatformResult>;

  vk(url: string): Promise<PlatformResult>;

  weibo(url: string): Promise<PlatformResult>;

  mixcloud(url: string): Promise<PlatformResult>;

  audiomack(url: string): Promise<PlatformResult>;
  dropbox(url: string): Promise<PlatformResult>;
  archiveorg(url: string): Promise<PlatformResult>;
  applepodcasts(url: string): Promise<PlatformResult>;
  audius(url: string): Promise<PlatformResult>;
  streamable(url: string): Promise<PlatformResult>;
  tumblr(url: string): Promise<PlatformResult>;
  bluesky(url: string): Promise<PlatformResult>;
  hearthisat(url: string): Promise<PlatformResult>;
  freemusicarchive(url: string): Promise<PlatformResult>;
  boxcom(url: string): Promise<PlatformResult>;
  box(url: string): Promise<PlatformResult>;
  onedrive(url: string): Promise<PlatformResult>;
  loom(url: string): Promise<PlatformResult>;
  rutube(url: string): Promise<PlatformResult>;
  okru(url: string): Promise<PlatformResult>;
  bitchute(url: string): Promise<PlatformResult>;
  telegram(url: string): Promise<PlatformResult>;
  linkedin(url: string, opts?: AllDLOptions): Promise<PlatformResult>;
  lemon8(url: string, opts?: AllDLOptions): Promise<PlatformResult>;
  clapper(url: string, opts?: AllDLOptions): Promise<PlatformResult>;
  triller(url: string, opts?: AllDLOptions): Promise<PlatformResult>;

  info(url: string, opts?: InfoOptions): Promise<InfoResult>;

  setTimeout(ms: number): number;

  getTimeout(): number;

  setProxy(proxyUrl: string | string[] | null): unknown;

  getProxy(): string | string[] | null;

  getProxyStats(): ProxyStats;

  serve(opts?: { port?: number; apiKey?: string }): Promise<unknown>;

  playlist(url: string, opts?: PlaylistOptions): Promise<PlaylistResult>;

  playlistDownload(url: string, opts?: PlaylistDownloadOptions): Promise<PlaylistDownloadResult>;

  subtitles(url: string, opts?: { lang?: string; dest?: string }): Promise<SubtitleResult>;

  subtitlesToSrt(input: string): string;

  sourceHealth(): SourceHealthMap;

  checkSources(): Promise<SourceStatusMap>;
}

export declare const alldl: AllDL;
